/* DayPicker retains table semantics; its structural rows join the authored eight-column grid. */
[data-slot="calendar-grid"] {
  width: 100%;
  border-collapse: collapse;
}
[data-slot="calendar-grid"] :is(thead, tbody, tr) {
  display: contents;
}
[data-slot="calendar-grid"] td {
  display: grid;
  place-items: center;
  width: 100%;
  height: 40px;
  padding: 0;
}
:where([data-slot="calendar-grid"]) th:where(:not(.v-cal__wk)) {
  padding: 0;
}
[data-slot="calendar-header"] {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
[data-slot="calendar-months"],
[data-slot="calendar"] .v-cal__months {
  display: flex;
  gap: var(--s-6);
}
[data-slot="calendar"] .v-cal__month-wrap {
  display: grid;
  gap: 14px;
  min-width: 0;
  flex: 1;
}
[data-slot="calendar-day"][data-disabled],
[data-slot="calendar-day"]:disabled {
  cursor: not-allowed;
  color: var(--v-disabled-ink);
}
@media (max-width: 420px) {
  [data-slot="calendar-grid"] td {
    height: 36px;
  }
}

/* Semantic row headers retain the source span typography, including normal week weights. */
.v-cal__wk:where([data-slot="calendar-week-number"]) {
 font-weight: 400;
 text-align: start;
 vertical-align: baseline;
}

/* Authored weekday labels are spans; semantic table headers keep their alignment. */
.v-cal__wd:where([data-slot="calendar-weekday"], [data-slot="calendar-week-number-header"]) {
  text-align: start;
}

}
